/// <summary>
///     The <c>AVAInventTransferParmShipFrm_Extension</c> class is the extension for <c>InventTransferParmShip</c>
/// </summary>
[ExtensionOf(FormStr(InventTransferParmShip))]
final class AVAInventTransferParmShipFrm_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>init</c> method.
/// </summary>
public void init()
{
    next init();
}

/// <summary>
///     AVA <c>avaUpdateAutoReceive</c> method.
/// </summary>
public void avaUpdateAutoReceive()
{
    InventTransferParmUpdate        locInventTransferParmUpdate;
    InventTransferParmTable         locInventTransferParmTable;
    InventTransferAutoReceiveQty    locInventTransferAutoReceiveQty;
    InventTransferTable             locInventTransferTable;

    InventLocation                  locInventLocation;
    boolean                         locUpdatesDone;

    locInventTransferParmUpdate = InventTransferParmUpdate;
    locInventTransferParmTable  = InventTransferParmTable;

    ttsbegin;
    while select locInventTransferParmTable
    where locInventTransferParmTable.ParmId == locInventTransferParmUpdate.ParmId
    {
        locInventTransferTable                      = InventTransferTable::find(locInventTransferParmTable.TransferId);
        locInventLocation                           = InventLocation::find(locInventTransferTable.InventLocationIdTo);
        if(locInventLocation.RecId)
        {
            if(locInventLocation.WHSEnabled)
            {
                locInventTransferAutoReceiveQty     = NoYes::No;
            }
            else
            {
                locInventTransferAutoReceiveQty     = NoYes::Yes;
            }

            if (locInventTransferTable.KCS_TransferType == KCS_TransferType::Agent && locInventLocation.AVARelocationLocked)
            {
                locInventTransferAutoReceiveQty = NoYes::No;                
            }

            if(locInventTransferParmTable.AutoReceiveQty != locInventTransferAutoReceiveQty)
            {
                locInventTransferParmTable.selectForUpdate(true);
                locInventTransferParmTable.AutoReceiveQty   = locInventTransferAutoReceiveQty;
                locInventTransferParmTable.update();
                locUpdatesDone                              = true;
            }
        }
    }
    ttscommit;

    if(locUpdatesDone)
    {
        InventTransferParmTable_DS.refresh();
    }
}
